changeSet.sql:
ALTER TABLE whiteboard.whiteboard_draft_replay
 ADD CONSTRAINT whiteboard_draft_replay_base_sequence_ck CHECK (base_sequence >= 0),
 ADD CONSTRAINT whiteboard_draft_replay_head_sequence_ck CHECK (head_sequence >= base_sequence);
GRANT SELECT, INSERT, UPDATE, DELETE ON whiteboard.whiteboard_draft_replay TO ${app_user};

CREATE FUNCTION whiteboard.protect_draft_replay_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 -- Compactors must acquire space, page/board, then draft locks before pruning.
 -- The draft lock serializes retention checks with creation of new leases.
 PERFORM 1 FROM whiteboard.whiteboard_draft WHERE page_id = OLD.page_id FOR UPDATE;
 IF EXISTS (SELECT 1 FROM whiteboard.whiteboard_draft_replay
   WHERE page_id = OLD.page_id AND expires_at > clock_timestamp()
    AND base_sequence < OLD.sequence AND head_sequence >= OLD.sequence) THEN
  RAISE EXCEPTION 'update is retained by an active draft replay' USING ERRCODE = '55000';
 END IF;
 RETURN OLD;
END;
$$;
